begin;
create extension if not exists pgtap with schema extensions;
select plan(15);
select function_returns('public', 'apply_approved_publish_retry', array['uuid'], 'jsonb', 'approved retry apply RPC signature');
select ok((select p.prosecdef from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'apply_approved_publish_retry'), 'retry apply is security definer');
select ok(has_function_privilege('authenticated', 'public.apply_approved_publish_retry(uuid)', 'EXECUTE'), 'authenticated can request retry apply');
select ok(not has_function_privilege('anon', 'public.apply_approved_publish_retry(uuid)', 'EXECUTE'), 'anon cannot apply retry');
select ok(not has_function_privilege('service_role', 'public.apply_approved_publish_retry(uuid)', 'EXECUTE'), 'service role cannot call operator retry apply directly');
select ok((select pg_get_functiondef('public.apply_approved_publish_retry(uuid)'::regprocedure) like '%request_row.status <> ''approved''%'), 'only approved requests can apply');
select ok((select pg_get_functiondef('public.apply_approved_publish_retry(uuid)'::regprocedure) like '%request_row.expected_version%'), 'apply checks expected attempt version');
select ok((select pg_get_functiondef('public.apply_approved_publish_retry(uuid)'::regprocedure) like '%error_code is distinct from ''RESULT_UNKNOWN''%'), 'unknown provider result cannot be blindly retried');
select ok((select pg_get_functiondef('public.apply_approved_publish_retry(uuid)'::regprocedure) like '%approval_request_id%'), 'retry is idempotently bound to approval request');
select ok((select pg_get_functiondef('public.apply_approved_publish_retry(uuid)'::regprocedure) like '%publish.retry.applied%'), 'retry apply appends an audit event');
select ok((select pg_get_functiondef('public.apply_approved_publish_retry(uuid)'::regprocedure) like '%recovery_status = ''retry_ready''%'), 'only retry-ready failures can be applied');
select ok((select pg_get_functiondef('public.apply_approved_publish_retry(uuid)'::regprocedure) like '%approved-publish-retry:%'), 'retry idempotency key uses a separate domain');
select ok((select pg_get_functiondef('public.apply_approved_publish_retry(uuid)'::regprocedure) like '%status = ''failed''%'), 'schedule must still be failed before rescheduling');
select ok((select pg_get_constraintdef(oid) from pg_constraint where conrelid = 'public.platform_audit_events'::regclass and conname = 'platform_audit_events_action_check') like '%admin.account.activated%workspace.activation.requested%'), 'existing activation audit actions remain allowed');
select ok((select pg_get_constraintdef(oid) from pg_constraint where conrelid = 'public.platform_audit_events'::regclass and conname = 'platform_audit_events_action_check') like '%document.version.draft_created%' and (select pg_get_constraintdef(oid) from pg_constraint where conrelid = 'public.platform_audit_events'::regclass and conname = 'platform_audit_events_action_check') like '%document.version.reviewed%' and (select pg_get_constraintdef(oid) from pg_constraint where conrelid = 'public.platform_audit_events'::regclass and conname = 'platform_audit_events_action_check') like '%document.version.activated%' and (select pg_get_constraintdef(oid) from pg_constraint where conrelid = 'public.platform_audit_events'::regclass and conname = 'platform_audit_events_action_check') like '%credit.adjust.applied%', 'final audit action union remains allowed');
select * from finish();
rollback;
